UIBoxImage=function(game,id,selectedFunction,context){Phaser.Image.call(this,game,0,0,'box'+id);this.anchor.setTo(0.5,0.9);this.hitArea=new Phaser.Rectangle(-this.width*0.5/2,-this.height*0.9/2,this.width/2,this.height/2);this.id=id;this.selectedFunction=selectedFunction;this.context=context;this.unlocked=null;this.disabled=false;this.open=false;this.selected=false;this.spawnTween=null;this.removeTween=null;this.sizeTween=null;this.enable();this.events.onInputUp.add(this._onInputUpHandler,this);this.events.onInputOver.add(this._onInputOverHandler,this);this.events.onInputOut.add(this._onInputOutHandler,this);this.kill();this.scale.set(0.0,0.0);}
UIBoxImage.prototype=Object.create(Phaser.Image.prototype);UIBoxImage.prototype.constructor=UIBoxImage;UIBoxImage.prototype.update=function(){if(!this.exists){return;}}
UIBoxImage.prototype.spawn=function(x,y,unlocked,delay){this.reset(x,y);this.scale.set(0.0,0.0);this.disabled=false;this.selected=false;if(this.open){this.frame=1;}else{this.frame=0;}this.unlocked=unlocked;if(this.unlocked){this.enable();}else{this.inputEnabled=false;this.tint=0x333333;}if(this.removeTween){this.removeTween.stop();this.removeTween=null;}if(this.sizeTween){this.sizeTween.stop();}if(this.open){this.select();}else{this.spawnTween=this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true,delay);}}
UIBoxImage.prototype._onInputUpHandler=function(sprite,pointer){this.selectedFunction(this,this.context);}
UIBoxImage.prototype._onInputOverHandler=function(sprite,pointer){if(!this.selected&&!this.disabled){this.sizeTween=this.game.add.tween(this.scale).to({x:1.1,y:1.1},UIConstants.ELEMENT_SELECTION_TIME,Phaser.Easing.Back.Out,true);}}
UIBoxImage.prototype._onInputOutHandler=function(sprite,pointer){if(!this.selected&&!this.disabled){this.sizeTween=this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_DESELECTION_TIME,Phaser.Easing.Back.Out,true);}}
UIBoxImage.prototype.deselect=function(){this.selected=false;this.sizeTween=this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_SELECTION_TIME,Phaser.Easing.Back.Out,true);}
UIBoxImage.prototype.select=function(){this.selected=true;this.sizeTween=this.game.add.tween(this.scale).to({x:1.2,y:1.2},UIConstants.ELEMENT_SELECTION_TIME,Phaser.Easing.Back.Out,true);}
UIBoxImage.prototype.disable=function(){this.disabled=true;this.inputEnabled=false;}
UIBoxImage.prototype.enable=function(){if(!this.open&&this.unlocked){this.disabled=false;this.inputEnabled=true;this.input.useHandCursor=true;}}
UIBoxImage.prototype.openBox=function(){if(!this.open){this.open=true;this.disable();this.frame=1;}}
UIBoxImage.prototype.closeBox=function(){if(this.open){this.open=false;this.enable();this.frame=0;}}
UIBoxImage.prototype.getId=function(){return this.id;}
UIBoxImage.prototype.remove=function(){this.disable();if(this.spawnTween){this.spawnTween.stop();}if(this.sizeTween){this.sizeTween.stop();}if(!this.removeTween){this.removeTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.removeTween.onComplete.add(function(){this.removeTween=null;this.kill();},this);}}
UIBoxImage.prototype.retire=function(){this.kill();}